[HttpGet("movies/{id}")]
[Produces("application/json", "application/xml", "text/html")]
public async Task<IActionResult> Get(long id)
{
    var movie = await _service.FindAsync(id);       // one model for every format
    if (movie is null) return NotFound();
    return WantsHtml() ? View("Movie", movie)      // Razor representation
                       : Ok(MovieDto.From(movie));  // formatter representation
}
